def aizt_rewrite(
    user_content: Optional[str] = None,
    messages: Optional[List[Dict]] = None,
    system_content: str = "You are a helpful assistant.",
    to_json: bool = False,
    model_type: str = "qwen3",
    lora_name: str = None,
    temperature: int = 0,
    presence_penalty: int = 0.5,
    frequency_penalty: int = 1,
    **kwargs
) -> Union[str, Dict]:
    """与Qwen模型对话
    
    参数:
        user_content: 用户消息内容
        messages: 对话历史消息列表
        system_content: 系统消息内容
        to_json: 是否将响应解析为JSON
        **kwargs: 其他API参数
        
    返回:
        模型响应字符串或解析后的JSON
        
    异常:
        ValueError: 如果没有提供user_content或messages
    """
   
    try:
        if not (user_content or messages):
            raise ValueError("Must provide either user_content or messages")
        
        # 准备消息
        if messages:
            chat_messages = messages
        else:
            chat_messages = [
                {"role": "system", "content": system_content},
                {"role": "user", "content": user_content}
            ]
        
        extra_body = {
            "chat_template_kwargs": {
                "enable_thinking": False
            },
        }

        if lora_name is not None:
            extra_body['model'] = lora_name
        
        # if model_type == "qwen3":
        response = client_rewrite.chat.completions.create(
            model="Qwen/Qwen3.5-4B",
            messages=chat_messages,
            temperature=0,
            stream=False, 
            presence_penalty=presence_penalty,    # 控制新主题的出现（-2.0 到 2.0）
            frequency_penalty=frequency_penalty,   # 控制重复内容的出现（-2.0 到 2.0）
            extra_body=extra_body
        )
        # else:

        #     response = client_embedding.chat.completions.create(
        #         model=model_type,
        #         messages=chat_messages,
        #         temperature=0,
        #         stream=False, 
        #         presence_penalty=0.5,    # 控制新主题的出现（-2.0 到 2.0）
        #         frequency_penalty=1,   # 控制重复内容的出现（-2.0 到 2.0）
        #         extra_body=extra_body
        #     )
        content = response.choices[0].message.content


        return content
    except Exception as e:
        raise Exception(f"QwenAI-API请求失败: {str(e)}")

def aizt_embedding(
    input_text: Union[str, List[str]],
    model_type: str = "Qwen/Qwen3-Embedding-0.6B",
    lora_name: str = None,
    to_json: bool = False,
    **kwargs
) -> Union[List[float], Dict]:
    """调用 Qwen embedding 模型

    参数:
        input_text: 输入文本或文本列表
        model_type: 模型名称 (默认为 qwen-30.6b-embedding)
        lora_name: LoRA 名称（如需覆盖模型）
        to_json: 是否返回完整 JSON
        **kwargs: 其他 API 参数

    返回:
        向量 embedding (list[float]) 或完整 JSON
    """

    try:
        # 如果指定了 lora_name，则覆盖模型
        if lora_name is not None:
            model_type = lora_name


        response = client_embedding.embeddings.create(
            model=model_type,
            input=input_text,
        )

        # if to_json:
        #     return response.dict()

        # 如果输入是单条文本
        # if isinstance(input_text, str):
        #     return response.data[0].embedding

        # 如果输入是多条文本
        return response.data[0].embedding

    except Exception as e:
        raise Exception(f"QwenAI-Embedding API 请求失败: {str(e)}")


def aizt_ocr(img_b64):
    try:
        img_data_url = f"data:image/jpeg;base64,{img_b64}"
        messages = [
                        {
                            "role": "user",
                            "content": [
                                {
                                    "type": "image_url",
                                    "image_url": {"url": img_data_url}
                                },
                                {
                                    "type": "text",
                                    "text": "OCR:"
                                }
                            ]
                        }
                    ]

        response = client_ocr.chat.completions.create(
            model="PaddlePaddle/PaddleOCR-VL",
            messages=messages,
            temperature=0.0,
        )
        # print(f"Generated text: {response.choices[0].message.content}")
        return response.choices[0].message.content
    except Exception as e:
        raise Exception(f"PaddleOCR请求失败: {str(e)}")


def aizt_rerank(
    user_query: str,
    rerank_docs: List[str],
    model_type: str = "Qwen/Qwen3-Reranker-8B",
    lora_name: str = None,
    **kwargs,
) -> List[float]:
    """对召回结果做精排，返回与输入文档一一对应的分数列表。"""

    if not user_query or not isinstance(user_query, str):
        raise ValueError("user_query 必须是非空字符串")
    if rerank_docs is None:
        raise ValueError("top_10_list 不能为空")

    documents = []
    for doc in rerank_docs:
        if isinstance(doc, str):
            documents.append(doc)
        elif isinstance(doc, dict):
            documents.append(str(doc.get("content", "")))
        else:
            documents.append(str(doc))
    model_name = lora_name or model_type

    def _extract_score(item: Dict) -> Optional[float]:
        if not isinstance(item, dict):
            return None
        for key in ("score", "relevance_score", "similarity", "logit"):
            if key in item:
                try:
                    return float(item[key])
                except Exception:
                    return None
        return None

    # endpoint_candidates = [
    #     kwargs.pop("endpoint", None),
    #     "rerank",
    #     "v1/rerank",
    #     "rank",
    #     "v1/rank",
    #     "/rerank",
    #     "/v1/rerank",
    #     "/rank",
    #     "/v1/rank",
    # ]
    # endpoint_candidates = [x for x in endpoint_candidates if x]

    def _post_with_fallback(body: Dict) -> Dict:

        last_error = None
        # for endpoint in endpoint_candidates:
        try:
            # if endpoint.startswith("http://") or endpoint.startswith("https://"):
            #     url = endpoint
            # else:
            #     url = f"{rerank_url.rstrip('/')}/{endpoint.lstrip('/')}"
            resp = requests.post(rerank_url, json=body, timeout=15)
            resp.raise_for_status()
            res = resp.json()
            scores = [item["score"] for item in res["result"]]
            return {"scores": scores}
        except Exception as e:
            last_error = e
            logger.warning("rerank 请求 endpoint=%s 失败: %s", rerank_url, str(e))
        raise last_error if last_error else RuntimeError("rerank 请求失败，未找到可用 endpoint")

    def _batch_mode() -> List[float]:
        body = {
            # "model": model_name,
            "query": user_query,
            "document": documents,
        }
        body.update(kwargs)
        resp = _post_with_fallback(body)

        # 兼容常见返回格式：
        # 1) {"results":[{"index":0,"relevance_score":...}, ...]}
        # 2) {"data":[{"index":0,"score":...}, ...]}
        # 3) {"scores":[...]}
        if isinstance(resp, dict):
            if isinstance(resp.get("scores"), list):
                return [float(s) for s in resp["scores"]]

            items = resp.get("results") or resp.get("data")
            if isinstance(items, list):
                scores = [0.0] * len(documents)
                filled = 0
                for i, item in enumerate(items):
                    if not isinstance(item, dict):
                        continue
                    idx = item.get("index", i)
                    score = _extract_score(item)
                    if score is None:
                        continue
                    if isinstance(idx, int) and 0 <= idx < len(scores):
                        scores[idx] = score
                        filled += 1
                if filled == len(documents):
                    return scores
                # 如果后端没返回 index，就按顺序回填
                if filled == 0 and len(items) == len(documents):
                    seq_scores = [_extract_score(x) for x in items]
                    if all(s is not None for s in seq_scores):
                        return [float(s) for s in seq_scores]
        raise ValueError(f"无法解析 rerank 批量返回: {resp}")

    def _single_mode() -> List[float]:
        scores = []
        for doc in documents:
            body = {
                "model": model_name,
                "query": user_query,
                "document": doc,
            }
            body.update(kwargs)
            resp = _post_with_fallback(body)
            score = _extract_score(resp) if isinstance(resp, dict) else None
            if score is None and isinstance(resp, dict):
                items = resp.get("results") or resp.get("data")
                if isinstance(items, list) and items:
                    score = _extract_score(items[0])
            if score is None:
                raise ValueError(f"无法解析 rerank 单条返回: {resp}")
            scores.append(float(score))
        return scores

    try:
        return _batch_mode()
    except Exception as e_batch:
        logger.warning(f"rerank 批量模式失败，回退单条模式: {e_batch}")
        try:
            return _single_mode()
        except Exception as e_single:
            raise Exception(f"Rerank API 请求失败: batch={e_batch}; single={e_single}")

