def batch_call_aizt_chat(
    prompts: Optional[List[str]] = None,
    messages_list: Optional[List[List[Dict]]] = None,
    system_content: str = "You are a helpful assistant.",
    to_json: bool = False,
    model_type: str = "Qwen/Qwen3-8B",
    lora_name: str = None,
    max_workers: int = 5,
    **kwargs
) -> List[Dict]:
    """批量调用 aizt_chat，支持传入 prompts 或 messages_list

    参数:
        prompts: 用户消息内容列表（与 messages_list 二选一）
        messages_list: 对话历史消息列表（与 prompts 二选一）
        system_content: 系统消息内容
        to_json: 是否将响应解析为JSON
        model_type: 模型类型
        max_workers: 线程池最大工作线程数
        **kwargs: 其他传递给 aizt_chat 的参数

    返回:
        模型响应列表（每个元素为字符串或解析后的JSON）

    异常:
        部分失败时返回部分结果，并记录错误日志
    """
    if (prompts is None and messages_list is None) \
        or (prompts is not None and messages_list is not None):
        raise ValueError("必须提供 prompts 或 messages_list 中的一个，且不能同时提供")

    results = []
    failed_indices = []

    def _call_aizt_chat(input_data: Union[str, List[Dict]], index: int):
        try:
            if isinstance(input_data, str):
                # 使用 prompts
                result = aizt_chat(
                    user_content=input_data,
                    system_content=system_content,
                    to_json=to_json,
                    model_type=model_type,
                    lora_name=lora_name,
                    **kwargs
                )
            else:
                # 使用 messages_list
                result = aizt_chat(
                    messages=input_data,
                    system_content=system_content,
                    to_json=to_json,
                    model_type=model_type,
                    lora_name=lora_name,
                    **kwargs
                )
            return result
        except Exception as e:
            logger.error(f"批量调用 aizt_chat 失败 (输入索引 {index}): {str(e)}")
            failed_indices.append(index)
            return None

    input_data_list = prompts if prompts is not None else messages_list

    with concurrent.futures.ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = {
            executor.submit(_call_aizt_chat, input_data, index): index
            for index, input_data in enumerate(input_data_list)
        }
        for future in concurrent.futures.as_completed(futures):
            index = futures[future]
            try:
                result = future.result()
                if result is not None:
                    results.append(result)
            except Exception as e:
                logger.error(f"批量调用 aizt_chat 异常 (输入索引 {index}): {str(e)}")
                failed_indices.append(index)

    if failed_indices:
        logger.warning(f"批量调用 aizt_chat 部分失败，失败索引: {failed_indices}")

    return results






def _aizt_clean_keywords(kws: List[str], max_n: int) -> List[str]:
    if not kws:
        return []
    seen = set()
    out = []
    for kw in kws:
        if not isinstance(kw, str):
            continue
        s = kw.strip()
        if not s:
            continue
        s = s.strip("\"'“”‘’`")
        s = re.sub(r"\s+", " ", s)

        # 过滤纯标点
        if re.fullmatch(r"[\W_]+", s):
            continue
        # 太长通常不是“关键词”（可按需放宽）
        if len(s) > 40:
            continue

        key = s.lower()
        if key in seen:
            continue
        seen.add(key)
        out.append(s)
        if len(out) >= max_n:
            break
    return out

def _aizt_fallback_keywords(text: str, max_high: int, max_low: int) -> Tuple[List[str], List[str]]:
    t = (text or "").strip()
    if not t:
        return [], []
    parts = re.split(r"[，,。;；、\n\t]+", t)
    parts = [p.strip() for p in parts if p.strip()]
    # low：取更短的更像实体/术语
    low = sorted(parts, key=len)[:max_low]
    low = _aizt_clean_keywords(low, max_low)
    # high：取更长的更像主题
    high = sorted(parts, key=len, reverse=True)[:max_high]
    high = _aizt_clean_keywords(high, max_high)
    return high, low

def _extract_json_object(text: str) -> Optional[str]:
    """
    从模型输出中尽量提取第一个 JSON 对象 {...}
    兼容模型偶尔输出多余说明、markdown 代码块等情况
    """
    if not text:
        return None
    # 先去掉 ```json ``` 包裹
    t = re.sub(r"```(?:json)?\s*", "", text)
    t = t.replace("```", "").strip()

    # 直接尝试整体解析
    try:
        json.loads(t)
        return t
    except Exception:
        pass

    # 提取第一个大括号对象（最常见）
    m = re.search(r"\{.*\}", t, flags=re.S)
    if m:
        candidate = m.group(0)
        try:
            json.loads(candidate)
            return candidate
        except Exception:
            return candidate  # 先返回，外层再 try/except
    return None

def aizt_extract_keyword(
    query: str,
    *,
    language: str = "zh",                 # "zh" / "en" 等，用于提示输出语言
    kb_hint: Optional[str] = None,        # 可选：知识库领域提示，比如“医学”“金融”“你们kb名”
    max_high_level: int = 6,
    max_low_level: int = 10,
    model_type: str = "qwen3",
    lora_name: str = None,
    return_json: bool = False,            # True -> 返回 dict（带两类关键词）；False -> 返回 (hl,ll)
) -> Union[Tuple[List[str], List[str]], Dict]:
    """
    LightRAG 风格关键词抽取：
    - high_level_keywords：抽象主题/机制/任务（用于 GLOBAL search）
    - low_level_keywords：实体/术语/缩写/数值单位（用于 LOCAL search）

    返回：
    - 默认返回 (high_level_keywords, low_level_keywords)
    - return_json=True 时返回 {"high_level_keywords":..., "low_level_keywords":...}
    """
    if not query or not query.strip():
        if return_json:
            return {"high_level_keywords": [], "low_level_keywords": []}
        return [], []

    kb_part = f"\nKnowledge base hint: {kb_hint}\n" if kb_hint else ""



    examples = "\n".join(PROMPTS["keywords_extraction_examples"])

    kw_prompt = PROMPTS["keywords_extraction"].format(
    query=query,
    examples=examples,
    language=language)

    # 调用你现有的 aizt_chat
    raw = aizt_chat(
        user_content=kw_prompt,
        system_content="You are a precise information extraction assistant. Output JSON only.",
        to_json=False,
        model_type=model_type,
        lora_name=lora_name,
    )

    json_text = _extract_json_object(raw)
    if not json_text:
        hl, ll = _aizt_fallback_keywords(query, max_high_level, max_low_level)
        data = {"high_level_keywords": hl, "low_level_keywords": ll}
        return data if return_json else (hl, ll)

    try:
        data = json.loads(json_text)
    except Exception:
        # 有时模型会输出“近似 JSON”，这里你也可以换成 json_repair.loads
        # 但你当前 aizt_chat 没引 json_repair，我先用兜底
        hl, ll = _aizt_fallback_keywords(query, max_high_level, max_low_level)
        data = {"high_level_keywords": hl, "low_level_keywords": ll}
        return data if return_json else (hl, ll)

    hl = _aizt_clean_keywords(data.get("high_level_keywords", []), max_high_level)
    ll = _aizt_clean_keywords(data.get("low_level_keywords", []), max_low_level)

    # 兜底：避免空
    if not hl and not ll:
        hl, ll = _aizt_fallback_keywords(query, max_high_level, max_low_level)

    data_out = {"high_level_keywords": hl, "low_level_keywords": ll}
    return data_out if return_json else (hl, ll)
